Mesh<Point, double> mesh;
if (rt.number_of_vertices() == 0) {
    return mesh;
}

// Reserve space for vertices and edges
mesh.reserve_vertices(rt.number_of_vertices());
mesh.reserve_edges(rt.number_of_facets() * 2); // Upper bound estimate

// Map to store vertex handles by triangulation vertex
std::unordered_map<typename RT::Vertex_handle, typename Mesh<Point, double>::Vertex_handle> vertex_map;

// First pass: add all vertices to the mesh
for (auto vit = rt.finite_vertices_begin(); vit != rt.finite_vertices_end(); ++vit) {
    auto vh = mesh.add_vertex(vit->point());
    vertex_map[vit] = vh;
}

// Second pass: process facets and add edges
for (auto fit = rt.finite_facets_begin(); fit != rt.finite_facets_end(); ++fit) {
    // Get the dual points of the facet's vertices
    auto dual_points = rt.dual(fit);

    // Check if the dual points are finite and the facet meets the threshold
    if (dual_points.first != CGAL::ORIGIN && dual_points.second != CGAL::ORIGIN) {
        double area = std::abs(rt.triangle(fit).area());
        if (area >= threshold) {
            // Get the corresponding mesh vertices
            auto vh1 = vertex_map[fit->first->vertex((fit->second + 1) % 4)];
            auto vh2 = vertex_map[fit->first->vertex((fit->second + 2) % 4)];

            // Add edge to the mesh
            auto edge = mesh.add_edge(vh1, vh2);
            mesh.set_face_property(edge, area);
        }
    }
}

return mesh;
// END_CODE

